# -*- coding: utf-8 -*-
"""Xiaomi account binding endpoints.

The OAuth state lives inside the running MIoTClient instance, so bind/start
and bind/authorize must reach the same bridge process. A restart invalidates
an in-flight bind - the client must simply start over.
"""
from __future__ import annotations

from aiohttp import web

from ..core.errors import BridgeError, ErrorCode
from ..core.miot_service import XiaomiService
from .responses import ok


def _service(request: web.Request) -> XiaomiService:
    return request.app["service"]


async def get_account(request: web.Request) -> web.Response:
    return ok(await _service(request).account_status())


async def bind_start(request: web.Request) -> web.Response:
    service = _service(request)
    if service.bound:
        return ok({"bound": True, "already_bound": True})
    return ok(await service.generate_login_url())


async def bind_authorize(request: web.Request) -> web.Response:
    service = _service(request)
    try:
        body = await request.json()
    except Exception as err:  # noqa: BLE001
        raise BridgeError(ErrorCode.INVALID_ARGUMENT, f"invalid JSON body: {err}") from err
    if not isinstance(body, dict):
        raise BridgeError(ErrorCode.INVALID_ARGUMENT, "body must be a JSON object")
    raw = body.get("raw")
    if raw:
        return ok(await service.authorize_raw(str(raw)))
    code = body.get("code")
    state = body.get("state")
    if not code or not state:
        raise BridgeError(
            ErrorCode.INVALID_ARGUMENT, "provide raw, or code and state"
        )
    return ok(await service.authorize(str(code), str(state)))


async def unbind(request: web.Request) -> web.Response:
    return ok(await _service(request).unbind())

    A ?token= query value is also accepted for GET so <img> tags (camera
    snapshot / MJPEG) can authenticate without custom headers.
    """
    token = request.app["bridge_token"]
    if token and request.path not in PUBLIC_PATHS:
        header = request.headers.get("Authorization", "")
        query_token = request.query.get("token")
        header_ok = header == f"Bearer {token}"
        query_ok = request.method == "GET" and query_token == token
        if not header_ok and not query_ok:
            return error_response(
                BridgeError(ErrorCode.UNAUTHORIZED, "invalid or missing bridge token")
            )
    return await handler(request)


async def health(request: web.Request) -> web.Response:
    """Public: reachability, bind status and whether a token is required."""
    service: XiaomiService = request.app["service"]
    payload = await service.health()
    payload["auth_required"] = bool(request.app["bridge_token"])
    return web.json_response(payload)


async def local_token(request: web.Request) -> web.Response:
    """Reveal the bridge token to a loopback caller.

    This is a deliberate dev convenience: anyone who can reach the bridge from
    the machine it runs on is already trusted (they can read its env / token
    file). Remote callers are refused.
    """
    service: XiaomiService = request.app["service"]
    config = service.config
    remote = (request.remote or "").replace("::ffff:", "")
    if not config.allow_local_token:
        return error_response(
            BridgeError(ErrorCode.UNAUTHORIZED, "local token reveal is disabled")
        )
    if remote not in LOOPBACK:
        return error_response(
            BridgeError(
                ErrorCode.UNAUTHORIZED,
                "only a loopback caller may read the bridge token; type it in manually",
            )
        )
    return web.json_response(
        {"success": True, "bridge_token": config.bridge_token}
    )


async def auth_check(request: web.Request) -> web.Response:
    """Protected probe: 200 only when the caller presented a valid token.

    The page uses this to decide between the auth gate and the dashboard,
    instead of inferring auth state from whichever call happens to fail.
    """
    return web.json_response(
        {"success": True, "auth_required": bool(request.app["bridge_token"])}
    )


def create_app(service: XiaomiService) -> web.Application:
    """Build the REST application."""
    app = web.Application(middlewares=[error_middleware, auth_middleware])
    app["service"] = service
    app["bridge_token"] = service.config.bridge_token
    app["camera_manager"] = None

    router = app.router
    router.add_get("/", web_ui.index)
    router.add_get("/api/health", health)
    router.add_get("/api/auth/check", auth_check)
    router.add_get("/api/auth/local-token", local_token)

    router.add_get("/api/devices", device_api.list_devices)
    router.add_get("/api/devices/{device_id}", device_api.get_device)
    router.add_get("/api/devices/{device_id}/spec", device_api.get_device_spec)
    router.add_get("/api/devices/{device_id}/property", device_api.get_property)
    router.add_post("/api/devices/{device_id}/property", device_api.set_property)
    router.add_post("/api/devices/{device_id}/action", device_api.call_action)

    router.add_get("/api/scenes", device_api.list_scenes)
    router.add_post("/api/scenes/{scene_id}/run", device_api.run_scene)

    router.add_get("/api/cameras", camera_api.list_cameras)
    router.add_get("/api/cameras/{device_id}/snapshot.jpg", camera_api.snapshot)
    router.add_get("/api/cameras/{device_id}/stream.mjpg", camera_api.stream)

    router.add_get("/api/xiaomi/account", account_api.get_account)
    router.add_post("/api/xiaomi/bind/start", account_api.bind_start)
    router.add_post("/api/xiaomi/bind/authorize", account_api.bind_authorize)
    router.add_post("/api/xiaomi/unbind", account_api.unbind)

    router.add_get("/api/sync", sync_api.get_sync)
    router.add_get("/api/sync/changes", sync_api.get_sync_changes)
    return app


async def run_http_server(service: XiaomiService) -> web.AppRunner:
    """Start the REST server and return the runner for shutdown."""
    app = create_app(service)
    runner = web.AppRunner(app)
    await runner.setup()
    site = web.TCPSite(runner, service.config.host, service.config.http_port)
    await site.start()
    _LOGGER.info("REST listening on %s:%s", service.config.host, service.config.http_port)
    return runner
# -*- coding: utf-8 -*-
"""Device, property, action and scene endpoints."""
from __future__ import annotations

from typing import Any, Dict, Tuple

from aiohttp import web

from ..core.errors import BridgeError, ErrorCode
from ..core.miot_service import XiaomiService
from .responses import ok


def _service(request: web.Request) -> XiaomiService:
    return request.app["service"]


async def _json_body(request: web.Request) -> Dict[str, Any]:
    try:
        body = await request.json()
    except Exception as err:  # noqa: BLE001
        raise BridgeError(ErrorCode.INVALID_ARGUMENT, f"invalid JSON body: {err}") from err
    if not isinstance(body, dict):
        raise BridgeError(ErrorCode.INVALID_ARGUMENT, "body must be a JSON object")
    return body


def _iid_from_body(body: Dict[str, Any]) -> Tuple[int, int]:
    """Accept siid+piid, or property='prop.<siid>.<piid>'.

    Semantic property names (power/brightness) need the MIoT spec mapping and
    are scheduled for Phase 2; until then the raw iid form is authoritative.
    """
    if "siid" in body and "piid" in body:
        return int(body["siid"]), int(body["piid"])
    prop = body.get("property")
    if isinstance(prop, str):
        parts = prop.split(".")
        if len(parts) == 3 and parts[0] == "prop" and parts[1].isdigit() and parts[2].isdigit():
            return int(parts[1]), int(parts[2])
    raise BridgeError(
        ErrorCode.INVALID_ARGUMENT,
        "provide siid+piid, or property='prop.<siid>.<piid>' (semantic names land in Phase 2)",
    )


async def list_devices(request: web.Request) -> web.Response:
    devices = await _service(request).public_devices()
    return ok({"devices": devices, "total": len(devices)})


async def get_device(request: web.Request) -> web.Response:
    state = await _service(request).get_device_state(request.match_info["device_id"])
    return ok(state)


async def get_device_spec(request: web.Request) -> web.Response:
    spec = await _service(request).get_device_spec(request.match_info["device_id"])
    return ok({"spec": spec})


async def get_property(request: web.Request) -> web.Response:
    service = _service(request)
    device_id = request.match_info["device_id"]
    did = await service.resolve_did(device_id)
    siid = request.query.get("siid")
    piid = request.query.get("piid")
    if not siid or not piid:
        raise BridgeError(ErrorCode.INVALID_ARGUMENT, "siid and piid query params are required")
    return ok(await service.get_property(did, int(siid), int(piid)))


async def set_property(request: web.Request) -> web.Response:
    service = _service(request)
    body = await _json_body(request)
    did = await service.resolve_did(request.match_info["device_id"])
    siid, piid = _iid_from_body(body)
    if "value" not in body:
        raise BridgeError(ErrorCode.INVALID_ARGUMENT, "value is required")
    return ok(await service.set_property(did, siid, piid, body["value"]))


async def call_action(request: web.Request) -> web.Response:
    service = _service(request)
    body = await _json_body(request)
    did = await service.resolve_did(request.match_info["device_id"])
    if "siid" not in body or "aiid" not in body:
        raise BridgeError(ErrorCode.INVALID_ARGUMENT, "siid and aiid are required")
    arguments = body.get("arguments") or body.get("in") or []
    if not isinstance(arguments, list):
        raise BridgeError(ErrorCode.INVALID_ARGUMENT, "arguments must be a list")
    return ok(await service.call_action(did, int(body["siid"]), int(body["aiid"]), arguments))


async def list_scenes(request: web.Request) -> web.Response:
    scenes = await _service(request).get_scenes()
    return ok(
        {
            "scenes": [
                {
                    "id": scene_id,
                    "name": getattr(scene, "scene_name", ""),
                    "home_id": getattr(scene, "home_id", None),
                    "room_id": getattr(scene, "room_id", None),
                }
                for scene_id, scene in scenes.items()
            ],
            "total": len(scenes),
        }
    )


async def run_scene(request: web.Request) -> web.Response:
    return ok(await _service(request).run_scene(request.match_info["scene_id"]))

